insert into public.training_drills (is_template,title,category,difficulty,role_tags,duration_minutes,objective,setup,steps,success_criteria,scoring_rubric,tags,archived)
select true,v.title,v.category,v.difficulty,v.roles,v.duration,v.objective,v.setup,v.steps,v.success,'{}'::jsonb,v.tags,false
from (values
('Primary Entry Timing & Safe Exit','role','advanced',array['P1 Primary Rusher'],15,'Clean opening without overcommit.','Custom room: P1 entry, P2 trade-ready.',array['IGL gives target + timing.','P1 confirms and enters on cue.','P2 holds trade distance and calls contact.','P1 disengages if trade window is lost.'],'Synchronized entry; P1 is not isolated; disengage call obeyed.',array['entry','trade','rusher']),
('P2 Trade Window & Pair Distance','backup','advanced',array['P2 Secondary Rusher'],15,'Convert P1 contact into a coordinated trade.','2v2/4v4 custom; line of sight and push cue.',array['P2 confirms ready before P1 commits.','P1 calls contact and direction.','P2 trades inside agreed window.','Both call result and reset.'],'No late uncoordinated push.',array['trade','backup','coordination']),
('P3 Flank Route & Timing Discipline','flank','advanced',array['P3 Third Rusher / Flanker'],20,'Apply flank pressure while preserving regroup options.','Custom room with primary fight and alternate route.',array['P3 reports route and ETA.','IGL approves timing.','P3 checks crossfire and exit.','P3 calls pressure before contact.','Regroup if primary fight moves.'],'Flank is communicated; team retains regroup path.',array['flank','information','positioning']),
('P4 Sniper Info & IGL Call Loop','igl','medium',array['P4 Sniper + IGL'],15,'Turn visual info into concise executable calls.','Squad custom; P4 observes and calls.',array['P4 reports count, direction, distance.','IGL gives action, timing, fallback.','Players acknowledge.','P4 updates changed information.'],'Calls are specific, acknowledged and updated.',array['igl','communication','macro']),
('Four-Player Focus Fire & Target Switch','squad-coordination','advanced',array['All players'],15,'Synchronize target priority and avoid split damage.','Custom room; one caller; 3 target switches.',array['Caller names target and direction.','Squad confirms target.','Focus until knock/retreat cue.','Caller announces switch.'],'Three clean switches without split focus.',array['focus-fire','target-priority','teamwork']),
('Zone Edge Hold & Exit Route','rotation','advanced',array['P4 Sniper + IGL','All players'],20,'Prepare zone-edge hold with clear exit.','BR custom; route, cover and fallback.',array['IGL identifies zone and route.','P3 checks flank info.','P4 covers and calls threats.','P1/P2 hold ready positions.','Rotate on trigger; regroup.'],'Early rotation; all four reach checkpoint.',array['zone','rotation','survival']),
('Endgame Cover Triangle','endgame','elite',array['All players'],20,'Create layered cover and controlled final-zone movement.','BR custom; 3–4 end-zone scenarios.',array['IGL assigns anchor, cover, move roles.','P4 calls threats and lanes.','P3 watches flank; P1/P2 move on cue.','Preserve utility and cover.','Review exposure.'],'No isolated movement; every move has cover/fallback.',array['endgame','positioning','cover']),
('Comms Under Pressure: 3-Word Calls','communication','medium',array['All players'],10,'Keep combat comms short and actionable.','Timed custom fights; short calls only.',array['Use location + threat + action.','One IGL decision voice.','Acknowledge orders.','Review after fight.'],'Critical info timely; calls concise; IGL clear.',array['communication','igl','clarity'])
) as v(title,category,difficulty,roles,duration,objective,setup,steps,success,tags)
where not exists(select 1 from public.training_drills d where d.is_template=true and d.title=v.title);